#!/usr/bin/env bash
set -euo pipefail
[ "$(git rev-parse --is-shallow-repository)" = false ] \
  || { echo "error: shallow clone; rev-list count would be wrong" >&2; exit 1; }

count=$(git rev-list --count --first-parent HEAD)
(( count < 65536 )) || { echo "error: count exceeds MSI build field" >&2; exit 1; }
date=$(git log -1 --format=%cs)
version="${date:2:2}.${date:5:2}.${count}"
version_bin="${date:2:2},${date:5:2},${count}"
year="${date:0:4}";
month="${date:5:2}";
day="${date:8:2}";
rev="$(git rev-parse --short=12 HEAD)";

cat > nix/version.nix <<EOF
# Generated by nix/version.sh — do not edit.
{
  version = "${version}";
  rev     = "$(git rev-parse --short=12 HEAD)";
}
EOF
cat >tip/rc/version.rc <<EOF
#define VER_FILEVERSION             ${version_bin},0
#define VER_FILEVERSION_STR         "${version}\0"
#define VER_PRODUCTVERSION          ${version_bin},0
#define VER_PRODUCTVERSION_STR      "${version}\0"
#define ABOUT_CAPTION_WITH_VER      "關於新酷音輸入法 (${version})\0"
#define ABOUT_VERSION_STR           "版本：${version}\0"
#define ABOUT_RELEASE_DATE_STR      "發行日期：${year} 年 ${month} 月 ${day} 日\0"
#define PREFS_TITLE_WITH_VER        "設定新酷音輸入法 (${version})\0"
EOF
cat >installer/version.json <<EOF
{
  "product_version": "${version},0",
  "build_date": "${year} 年 ${month} 月 ${day} 日"
}
EOF
cat >installer/version.wxi <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<Include>
    <?define Version = "${version}.0"?>
</Include>
EOF
